board=r'''function toggleBoardSelect(id){let p=gp(currentCase.id);if(!p.pinned.includes(id))return;if(boardSelection.includes(id))boardSelection=boardSelection.filter(x=>x!==id);else boardSelection.push(id);renderCase()}
function clearBoardSelection(){boardSelection=[];renderCase()}
function recoupSelected(){if(boardSelection.length<2){toast('Sélectionne au moins deux pièces à recouper');return}let c=currentCase,p=gp(c.id),chosen=new Set(boardSelection),matches=availableLinks(c).filter(l=>l.pair.every(id=>chosen.has(id))),added=0;matches.forEach(def=>{if(!p.links.includes(def.id)){p.links.push(def.id);added++}});if(matches.length){save();toast((added?added+' nouveau':'Recoupement déjà')+(added>1?'x liens établis':' lien établi')+' · '+matches.map(x=>x.title).join(' / '))}else toast('Aucun lien probant dans cette sélection. Retire ou ajoute des pièces.');renderCase()}
function renderBoardPremium(c,p){let defs=availableLinks(c),found=defs.filter(d=>p.links.includes(d.id)),n=boardSelection.length;return `<div class="board-v9"><section class="panel"><div class="sectiontitle"><div><h2>Mur de recoupement</h2><span class="muted">Sélectionne 2, 3, 4 pièces ou davantage. TRACE teste tous les liens possibles dans ta sélection.</span></div><span class="eyebrow">${p.pinned.length} ÉPINGLÉES</span></div><div class="board premium-board interactive-board">${p.pinned.length?p.pinned.map((id,i)=>{let e=c.evidence.find(x=>x.id===id),selected=boardSelection.includes(id);return e?`<button class="evidence-pin selectable ${selected?'selected':''}" onclick="toggleBoardSelect('${id}')" style="--r:${(i%2?1.2:-1.2)}deg"><span class="pin-dot"></span><span class="etype">${e.type}</span><b>${e.title}</b><small>${e.text.slice(0,95)}${e.text.length>95?'…':''}</small><em>${selected?'✓ SÉLECTIONNÉ':'TOUCHER POUR AJOUTER'}</em></button>`:''}).join(''):`<div class="board-empty"><b>Le mur est vide.</b><span>Épingle des pièces depuis « Preuves » pour commencer à construire ton faisceau.</span></div>`}</div><div class="recoup-action"><div><span class="eyebrow">RECOUPEMENT MULTIPLE</span><b>${n===0?'Choisis au moins 2 pièces':n===1?'1 pièce · ajoute-en au moins une':n+' pièces sélectionnées · prêt à recouper'}</b><small style="display:block;margin-top:5px;color:#788594">Tous les couples compatibles seront analysés en une fois.</small></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost" ${!n?'disabled':''} onclick="clearBoardSelection()">Effacer la sélection</button><button class="btn primary" ${n<2?'disabled':''} onclick="recoupSelected()">Recouper ${n>=2?n:''} pièce${n>1?'s':''} ↗</button></div></div></section><aside class="board-side"><section class="panel"><div class="sectiontitle"><h2>Liens établis</h2><span class="eyebrow">${found.length}/${defs.length}</span></div>${found.length?`<div class="link-results">${found.map(l=>`<article class="link-card"><span>${l.kind}</span><b>${l.title}</b><p>${l.text}</p></article>`).join('')}</div>`:`<div class="board-empty compact"><b>Aucun lien validé.</b><span>Tu peux sélectionner un faisceau complet de preuves : TRACE repère les recoupements pertinents sans limiter la sélection à deux.</span></div>`}</section><section class="panel"><h2>Carnet d’enquête</h2><p class="muted">Note tes horaires, contradictions et hypothèses.</p><textarea class="notes premium-notes" placeholder="Ex. : 02:14 = appel impossible / badge 4 à 02:18 / porte nord…" oninput="updateNotes(this.value)">${esc(p.notes||'')}</textarea><div class="notebook-guide"><span>HEURE</span><span>PERSONNE</span><span>CONTRADICTION</span><span>MOBILE</span></div></section></aside></div>`}'''
s=s[:a]+board+s[b:]

